PRAGMA foreign_keys=ON;
CREATE TABLE users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,password_salt TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE businesses(id TEXT PRIMARY KEY,owner_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,name TEXT NOT NULL,business_type TEXT DEFAULT 'Other',phone TEXT DEFAULT '',language TEXT DEFAULT 'en',currency TEXT DEFAULT 'ZAR');
CREATE TABLE sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash TEXT NOT NULL UNIQUE,expires_at TEXT NOT NULL);
CREATE TABLE products(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,name TEXT NOT NULL,sku TEXT DEFAULT '',kind TEXT DEFAULT 'product',selling_price INTEGER NOT NULL DEFAULT 0,cost_price INTEGER NOT NULL DEFAULT 0,stock_qty REAL NOT NULL DEFAULT 0,low_stock_threshold REAL NOT NULL DEFAULT 0,active INTEGER DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE customers(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,name TEXT NOT NULL,phone TEXT DEFAULT '',notes TEXT DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sales(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,customer_id TEXT REFERENCES customers(id),sale_date TEXT NOT NULL,payment_method TEXT NOT NULL,status TEXT DEFAULT 'paid',subtotal INTEGER NOT NULL,total INTEGER NOT NULL,amount_paid INTEGER DEFAULT 0,notes TEXT DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sale_items(id TEXT PRIMARY KEY,sale_id TEXT NOT NULL REFERENCES sales(id) ON DELETE CASCADE,product_id TEXT REFERENCES products(id),description TEXT NOT NULL,quantity REAL NOT NULL,unit_price INTEGER NOT NULL,unit_cost INTEGER DEFAULT 0,line_total INTEGER NOT NULL);
CREATE TABLE expenses(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,expense_date TEXT NOT NULL,category TEXT NOT NULL,description TEXT NOT NULL,amount INTEGER NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE payments(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,customer_id TEXT NOT NULL REFERENCES customers(id),sale_id TEXT REFERENCES sales(id),payment_date TEXT NOT NULL,amount INTEGER NOT NULL,method TEXT DEFAULT 'cash',note TEXT DEFAULT '');
CREATE TABLE stock_movements(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,product_id TEXT NOT NULL REFERENCES products(id),movement_date TEXT NOT NULL,movement_type TEXT NOT NULL,quantity REAL NOT NULL,note TEXT DEFAULT '');
CREATE TABLE audit_logs(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES businesses(id) ON DELETE CASCADE,user_id TEXT,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT,metadata TEXT DEFAULT '{}',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_sales_business_date ON sales(business_id,sale_date); CREATE INDEX idx_expenses_business_date ON expenses(business_id,expense_date); CREATE INDEX idx_products_business ON products(business_id); CREATE INDEX idx_customers_business ON customers(business_id); CREATE INDEX idx_sessions_expiry ON sessions(expires_at);
